content:
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background: linear-gradient(135deg, #1e2029 0%, #111317 100%);
  color: #f3f4f6;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 16px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

#root {
  width: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
}

/* 全体コンテナ */
.calculator-container {
  display: flex;
  flex-direction: column;
  gap: 20px;
  width: 100%;
  max-width: 400px;
  margin: 0 auto;
}

@media (min-width: 768px) {
  .calculator-container {
    max-width: 780px;
    flex-direction: row;
    align-items: flex-start;
  }
}

/* 電卓カード本体 */
.calculator-card {
  background: rgba(30, 34, 45, 0.85);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 28px;
  padding: 24px;
  box-shadow: 0 20px 45px rgba(0, 0, 0, 0.45), 0 0 1px rgba(255, 255, 255, 0.1);
  display: flex;
  flex-direction: column;
  gap: 20px;
  flex: 1;
  min-width: 0;
}

/* ヘッダー */
.calculator-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 4px;
}

.calculator-title {
  font-size: 1.15rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  color: #9ca3af;
  text-transform: uppercase;
}

/* ディスプレイ領域 */
.display-area {
  background: #11141b;
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: 18px;
  padding: 18px 20px;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  justify-content: center;
  min-height: 96px;
  overflow: hidden;
  box-shadow: inset 0 2px 6px rgba(0, 0, 0, 0.6);
}

.display-formula {
  font-size: 0.95rem;
  color: #9ca3af;
  min-height: 1.25rem;
  width: 100%;
  text-align: right;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: 500;
}

.display-current {
  font-size: 2.35rem;
  font-weight: 600;
  color: #ffffff;
  width: 100%;
  text-align: right;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  line-height: 1.2;
  letter-spacing: -0.02em;
}

/* キーパッド */
.keypad-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}

/* ボタン基本スタイル */
.calc-btn {
  font-family: inherit;
  appearance: none;
  border: none;
  outline: none;
  border-radius: 16px;
  height: 60px;
  font-size: 1.35rem;
  font-weight: 600;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.15s ease;
  user-select: none;
  -webkit-user-select: none;
  touch-action: manipulation;
}

.calc-btn:hover {
  filter: brightness(1.15);
  transform: translateY(-2px);
}

.calc-btn:active {
  filter: brightness(0.9);
  transform: translateY(1px) scale(0.98);
}

/* 数字ボタン */
.btn-number {
  background: #282d3c;
  color: #f9fafb;
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.2);
}

.btn-number:hover {
  background: #31374a;
}

/* 0ボタン（横長） */
.btn-zero {
  grid-column: span 2;
  border-radius: 16px;
}

/* 機能・アクションボタン (C, ±, %) */
.btn-action {
  background: #3a3f52;
  color: #d1d5db;
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.2);
}

.btn-action:hover {
  background: #464c63;
}

/* 演算子ボタン (÷, ×, -, +) */
.btn-operator {
  background: #4f46e5;
  color: #ffffff;
  box-shadow: 0 4px 12px rgba(79, 70, 229, 0.35);
}

.btn-operator:hover {
  background: #5b52f1;
}

/* イコールボタン (=) */
.btn-equal {
  background: #10b981;
  color: #ffffff;
  box-shadow: 0 4px 12px rgba(16, 185, 129, 0.35);
}

.btn-equal:hover {
  background: #059669;
}

/* 履歴パネル */
.history-panel {
  background: rgba(30, 34, 45, 0.85);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 28px;
  padding: 24px;
  box-shadow: 0 20px 45px rgba(0, 0, 0, 0.45), 0 0 1px rgba(255, 255, 255, 0.1);
  display: flex;
  flex-direction: column;
  flex: 1;
  min-width: 0;
  max-height: 520px;
}

.history-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-bottom: 16px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  margin-bottom: 14px;
}

.history-title {
  font-size: 1.15rem;
  font-weight: 700;
  color: #9ca3af;
  letter-spacing: 0.05em;
}

.clear-history-btn {
  background: transparent;
  border: 1px solid rgba(239, 68, 68, 0.3);
  color: #f87171;
  padding: 6px 12px;
  font-size: 0.85rem;
  font-weight: 500;
  border-radius: 10px;
  cursor: pointer;
  transition: all 0.2s ease;
}

.clear-history-btn:hover {
  background: rgba(239, 68, 68, 0.15);
  border-color: #ef4444;
  color: #fca5a5;
}

.clear-history-btn:active {
  transform: scale(0.97);
}

/* 履歴一覧 */
.history-list {
  list-style: none;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding-right: 4px;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.2) transparent;
}

.history-list::-webkit-scrollbar {
  width: 6px;
}

.history-list::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.2);
  border-radius: 3px;
}

.history-item {
  background: #191c24;
  border: 1px solid rgba(255, 255, 255, 0.04);
  border-radius: 12px;
  padding: 12px 16px;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 4px;
  transition: background 0.15s ease;
}

.history-item:hover {
  background: #212530;
}

.history-expression {
  font-size: 0.85rem;
  color: #9ca3af;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 100%;
}

.history-result {
  font-size: 1.2rem;
  font-weight: 600;
  color: #34d399;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 100%;
}

.history-empty {
  color: #6b7280;
  text-align: center;
  padding: 40px 16px;
  font-size: 0.95rem;
  line-height: 1.5;
}

@media (max-width: 360px) {
  body {
    padding: 8px;
  }

  .calculator-card,
  .history-panel {
    padding: 16px;
    border-radius: 20px;
  }

  .calc-btn {
    height: 52px;
    font-size: 1.2rem;
    border-radius: 12px;
  }

  .display-current {
    font-size: 1.85rem;
  }
}

export interface CalculationHistory {
  id: string;
  expression: string;
  result: string;
  timestamp: string;
}

export type OperatorType = '+' | '-' | '×' | '÷' | null;

import { useState, useEffect, useCallback } from 'react';
import { CalculationHistory, OperatorType } from './types';

export default function App() {
  const [currentValue, setCurrentValue] = useState<string>('0');
  const [previousValue, setPreviousValue] = useState<string | null>(null);
  const [operator, setOperator] = useState<OperatorType>(null);
  const [waitingForOperand, setWaitingForOperand] = useState<boolean>(false);
  const [formulaDisplay, setFormulaDisplay] = useState<string>('');
  const [history, setHistory] = useState<CalculationHistory[]>([
    {
      id: 'init-1',
      expression: '1,250 × 8',
      result: '10,000',
      timestamp: '12:00',
    },
    {
      id: 'init-2',
      expression: '10,000 - 1,500',
      result: '8,500',
      timestamp: '12:01',
    },
  ]);

  // 数値の整形（過度な桁数の切り捨て・誤差防止）
  const formatResult = (num: number): string => {
    if (!Number.isFinite(num)) {
      return 'エラー';
    }
    // 浮動小数点計算誤差を考慮して丸める
    const rounded = parseFloat(num.toPrecision(12));
    const str = rounded.toString();
    if (str.length > 12) {
      return rounded.toExponential(6);
    }
    return str;
  };

  // 数字入力ハンドラ
  const handleDigit = useCallback((digit: string) => {
    if (waitingForOperand) {
      setCurrentValue(digit);
      setWaitingForOperand(false);
    } else {
      if (currentValue === '0') {
        setCurrentValue(digit);
      } else {
        if (currentValue.length < 14) {
          setCurrentValue(currentValue + digit);
        }
      }
    }
  }, [currentValue, waitingForOperand]);

  // 小数点入力
  const handleDecimal = useCallback(() => {
    if (waitingForOperand) {
      setCurrentValue('0.');
      setWaitingForOperand(false);
      return;
    }
    if (!currentValue.includes('.')) {
      setCurrentValue(currentValue + '.');
    }
  }, [currentValue, waitingForOperand]);

  // 符号反転 (±)
  const handleToggleSign = useCallback(() => {
    if (currentValue === '0' || currentValue === 'エラー') return;
    if (currentValue.startsWith('-')) {
      setCurrentValue(currentValue.slice(1));
    } else {
      setCurrentValue('-' + currentValue);
    }
  }, [currentValue]);

  // パーセント計算 (%)
  const handlePercent = useCallback(() => {
    const val = parseFloat(currentValue);
    if (isNaN(val) || currentValue === 'エラー') return;

    if (previousValue !== null && operator !== null) {
      // 直前の値に対するパーセンテージを計算
      const prev = parseFloat(previousValue);
      const percentVal = (prev * val) / 100;
      setCurrentValue(formatResult(percentVal));
    } else {
      // 単独のパーセント計算（100で割る）
      const result = val / 100;
      setCurrentValue(formatResult(result));
    }
  }, [currentValue, previousValue, operator]);

  // 四則計算実行
  const executeCalculation = (a: number, b: number, op: OperatorType): number => {
    switch (op) {
      case '+':
        return a + b;
      case '-':
        return a - b;
      case '×':
        return a * b;
      case '÷':
        return b === 0 ? Infinity : a / b;
      default:
        return b;
    }
  };

  // 演算子入力 (+, -, ×, ÷)
  const handleOperator = useCallback((nextOperator: OperatorType) => {
    if (currentValue === 'エラー') return;

    const inputValue = parseFloat(currentValue);

    if (previousValue === null) {
      setPreviousValue(currentValue);
      setOperator(nextOperator);
      setFormulaDisplay(`${currentValue} ${nextOperator}`);
      setWaitingForOperand(true);
    } else if (operator) {
      if (waitingForOperand) {
        // 演算子の置き換え
        setOperator(nextOperator);
        setFormulaDisplay(`${previousValue} ${nextOperator}`);
        return;
      }

      const prev = parseFloat(previousValue);
      const computed = executeCalculation(prev, inputValue, operator);
      const formattedResult = formatResult(computed);

      setPreviousValue(formattedResult);
      setCurrentValue(formattedResult);
      setOperator(nextOperator);
      setFormulaDisplay(`${formattedResult} ${nextOperator}`);
      setWaitingForOperand(true);
    }
  }, [currentValue, previousValue, operator, waitingForOperand]);

  // イコール計算 (=)
  const handleEqual = useCallback(() => {
    if (!operator || previousValue === null || currentValue === 'エラー') {
      return;
    }

    const prev = parseFloat(previousValue);
    const current = parseFloat(currentValue);
    const expressionStr = `${previousValue} ${operator} ${currentValue}`;
    const computed = executeCalculation(prev, current, operator);
    const formattedResult = formatResult(computed);

    const now = new Date();
    const timeStr = `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;

    const newHistoryItem: CalculationHistory = {
      id: `${Date.now()}-${Math.random().toString(36).substring(2, 7)}`,
      expression: expressionStr,
      result: formattedResult,
      timestamp: timeStr,
    };

    setHistory((prevHistory) => [newHistoryItem, ...prevHistory]);
    setFormulaDisplay(`${expressionStr} =`);
    setCurrentValue(formattedResult);
    setPreviousValue(null);
    setOperator(null);
    setWaitingForOperand(true);
  }, [operator, previousValue, currentValue]);

  // オールクリア (AC / C)
  const handleClear = useCallback(() => {
    setCurrentValue('0');
    setPreviousValue(null);
    setOperator(null);
    setWaitingForOperand(false);
    setFormulaDisplay('');
  }, []);

  // 履歴クリア
  const handleClearHistory = () => {
    setHistory([]);
  };

  // 履歴アイテム選択で結果を再利用
  const handleSelectHistory = (result: string) => {
    if (result === 'エラー') return;
    setCurrentValue(result);
    setWaitingForOperand(false);
  };

  // キーボードイベントのバインド
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key >= '0' && e.key <= '9') {
        handleDigit(e.key);
      } else if (e.key === '.') {
        handleDecimal();
      } else if (e.key === '+') {
        handleOperator('+');
      } else if (e.key === '-') {
        handleOperator('-');
      } else if (e.key === '*') {
        handleOperator('×');
      } else if (e.key === '/') {
        e.preventDefault();
        handleOperator('÷');
      } else if (e.key === 'Enter' || e.key === '=') {
        e.preventDefault();
        handleEqual();
      } else if (e.key === 'Escape' || e.key === 'Delete') {
        handleClear();
      } else if (e.key === '%') {
        handlePercent();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleDigit, handleDecimal, handleOperator, handleEqual, handleClear, handlePercent]);

  const isClearAll = currentValue === '0' && previousValue === null;

  return (
    <div className="calculator-container">
      {/* 電卓本体カード */}
      <div className="calculator-card">
        <header className="calculator-header">
          <span className="calculator-title">電卓</span>
        </header>

        {/* 画面表示部 */}
        <div className="display-area">
          <div className="display-formula">{formulaDisplay}</div>
          <div className="display-current">{currentValue}</div>
        </div>

        {/* ボタンキーパッド */}
        <div className="keypad-grid">
          <button
            type="button"
            className="calc-btn btn-action"
            onClick={handleClear}
          >
            {isClearAll ? 'AC' : 'C'}
          </button>
          <button
            type="button"
            className="calc-btn btn-action"
            onClick={handleToggleSign}
          >
            ±
          </button>
          <button
            type="button"
            className="calc-btn btn-action"
            onClick={handlePercent}
          >
            %
          </button>
          <button
            type="button"
            className="calc-btn btn-operator"
            onClick={() => handleOperator('÷')}
          >
            ÷
          </button>

          <button
            type="button"
            className="calc-btn btn-number"
            onClick={() => handleDigit('7')}
          >
            7
          </button>
          <button
            type="button"
            className="calc-btn btn-number"
            onClick={() => handleDigit('8')}
          >
            8
          </button>
          <button
            type="button"
            className="calc-btn btn-number"
            onClick={() => handleDigit('9')}
          >
            9
          </button>
          <button
            type="button"
            className="calc-btn btn-operator"
            onClick={() => handleOperator('×')}
          >
            ×
          </button>

          <button
            type="button"
            className="calc-btn btn-number"
            onClick={() => handleDigit('4')}
          >
            4
          </button>
          <button
            type="button"
            className="calc-btn btn-number"
            onClick={() => handleDigit('5')}
          >
            5
          </button>
          <button
            type="button"
            className="calc-btn btn-number"
            onClick={() => handleDigit('6')}
          >
            6
          </button>
          <button
            type="button"
            className="calc-btn btn-operator"
            onClick={() => handleOperator('-')}
          >
            -
          </button>

          <button
            type="button"
            className="calc-btn btn-number"
            onClick={() => handleDigit('1')}
          >
            1
          </button>
          <button
            type="button"
            className="calc-btn btn-number"
            onClick={() => handleDigit('2')}
          >
            2
          </button>
          <button
            type="button"
            className="calc-btn btn-number"
            onClick={() => handleDigit('3')}
          >
            3
          </button>
          <button
            type="button"
            className="calc-btn btn-operator"
            onClick={() => handleOperator('+')}
          >
            +
          </button>

          <button
            type="button"
            className="calc-btn btn-number btn-zero"
            onClick={() => handleDigit('0')}
          >
            0
          </button>
          <button
            type="button"
            className="calc-btn btn-number"
            onClick={handleDecimal}
          >
            .
          </button>
          <button
            type="button"
            className="calc-btn btn-equal"
            onClick={handleEqual}
          >
            =
          </button>
        </div>
      </div>

      {/* 計算履歴パネル */}
      <div className="history-panel">
        <div className="history-header">
          <span className="history-title">計算履歴</span>
          {history.length > 0 && (
            <button
              type="button"
              className="clear-history-btn"
              onClick={handleClearHistory}
            >
              履歴を消去
            </button>
          )}
        </div>

        {history.length === 0 ? (
          <div className="history-empty">
            計算履歴はありません<br />
            計算を行うとここに自動記録されます
          </div>
        ) : (
          <ul className="history-list">
            {history.map((item) => (
              <li
                key={item.id}
                className="history-item"
                style={{ cursor: 'pointer' }}
                onClick={() => handleSelectHistory(item.result)}
                title="クリックしてこの値を入力欄に反映"
              >
                <span className="history-expression">{item.expression}</span>
                <span className="history-result">= {item.result}</span>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}
